 DrawNode::Image{at,width,height,mime,bytes}=>{point2(at,w,e)?;comma(w,e)?;w.number(*width,e)?;comma(w,e)?;w.number(*height,e)?;comma(w,e)?;w.string(mime,e)?;comma(w,e)?;w.octets(bytes,e)?}
 }w.delimiter(b"]",e)}
fn style(value:&DrawStyle,w:&mut Writer<'_,'_,'_>,e:SnapshotEncoding)->Result<(),ValueError>{w.delimiter(b"[",e)?;w.string(&value.name,e)?;comma(w,e)?;optional(value.fill.as_ref(),w,e,rgba)?;comma(w,e)?;optional(value.stroke.as_ref(),w,e,rgba)?;comma(w,e)?;optional(value.stroke_width.as_ref(),w,e,|value,w,e|w.number(*value,e))?;comma(w,e)?;optional(value.opacity.as_ref(),w,e,|value,w,e|w.number32(*value,e))?;w.delimiter(b"]",e)}
fn canvas(value:&DrawCanvas,w:&mut Writer<'_,'_,'_>,e:SnapshotEncoding)->Result<(),ValueError>{w.delimiter(b"[",e)?;w.number(value.width,e)?;comma(w,e)?;w.number(value.height,e)?;comma(w,e)?;optional(value.background.as_ref(),w,e,rgba)?;w.delimiter(b"]",e)}
pub(crate) fn fields(value:&SemioDrawingSnapshot,w:&mut Writer<'_,'_,'_>,e:SnapshotEncoding)->Result<(),ValueError>{w.entities(1)?;if e==SnapshotEncoding::Binary{w.byte(1)?}else{w.bytes(b"schema=")?}w.string(&value.schema,e)?;w.delimiter(b"\ncanvas=",e)?;canvas(&value.canvas,w,e)?;w.delimiter(b"\nstyles=",e)?;w.list(&value.styles,e,|w,value|style(value,w,e))?;w.delimiter(b"\nlayers=",e)?;w.list(&value.layers,e,|w,value|{w.delimiter(b"[",e)?;w.string(&value.id,e)?;comma(w,e)?;w.string(&value.name,e)?;comma(w,e)?;boolean(value.visible,w,e)?;comma(w,e)?;node(&value.root,w,e,0)?;w.delimiter(b"]",e)})}

